-- LABGAME V2 pre-validated 3/4-chapter plans generated from the 66-book
-- canon.ts and identical allocation algorithm to game-plan-next.ts.
-- Do NOT run against production until V2 release gates and backup pass.
-- Migration 202610160001 must be applied first; the V2 release switch remains FALSE.

DO $verify$
DECLARE v_len integer;v_days integer;v_chapters integer;v_bad integer;
BEGIN
 FOR v_len IN SELECT UNNEST(ARRAY[365,366]) LOOP
  SELECT COUNT(*),COUNT(DISTINCT day_number) INTO v_chapters,v_days
    FROM public.lab_v2_plan_chapters WHERE plan_length=v_len;
  SELECT COUNT(*) INTO v_bad FROM (
    SELECT day_number,COUNT(*) n FROM public.lab_v2_plan_chapters
    WHERE plan_length=v_len GROUP BY day_number
    HAVING COUNT(*) NOT IN (3,4) OR day_number>v_len
  ) invalid;
  IF v_chapters<>1189 OR v_days<>v_len OR v_bad<>0 THEN
   RAISE EXCEPTION 'Invalid V2 % stage plan: % chapters, % days, % invalid',v_len,v_chapters,v_days,v_bad;
  END IF;
 END LOOP;
END;
$verify$;
